return function(Plasma)
	local create = Plasma.create

	return Plasma.widget(function(text, options)
		options = options or {}

		options = options or {}
		local isOpened = options.isOpened
		local clicked, setClicked = Plasma.useState(false)
		local style = Plasma.useStyle()
		local refs = Plasma.useInstance(function(ref)
			return create("TextButton", {
				[ref] = "label",
				BackgroundTransparency = 0,
				BackgroundColor3 = style.bg3,
				Text = "",
				AutomaticSize = Enum.AutomaticSize.Y,
				Font = Enum.Font.GothamBold,
				TextSize = 24,
				TextStrokeTransparency = 1,
				TextXAlignment = Enum.TextXAlignment.Center,
				TextYAlignment = Enum.TextYAlignment.Center,
				TextWrapped = true,
				TextColor3 = Color3.new(1, 1, 1),
				Size = UDim2.new(1, 0, 0, 0),

				create("UIPadding", {
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
					PaddingTop = UDim.new(0, 8),
				}),

				create("UICorner"),

				Activated = function()
					setClicked(true)
				end
			})
		end)
		refs.label.Text = text
		refs.label.BackgroundColor3 = isOpened and style.primaryColor or style.bg3
		local handle = {
			clicked = function()
				if clicked then
					setClicked(false)
					return true
				end

				return false
			end,
		}
		return handle
	end)
end
